export default function event({ body }) {
  const login = body?.sender?.login,
    owner = body?.forkee?.owner?.login,
    repo = body?.repository?.full_name,
    url = body?.sender?.html_url;
  if ([login, owner, repo, url].some((x) => typeof x !== "string" || !x.trim()))
    throw Error("Fork event is missing sender, repository or profile");
  const parsed = new URL(url);
  if (
    parsed.protocol !== "https:" ||
    parsed.hostname !== "github.com" ||
    parsed.username ||
    parsed.password
  )
    throw Error("Invalid GitHub profile URL");
  return { login, owner, repo, url };
}

