export default async function people({ items, email, owner }, context) {
  if (!Array.isArray(items)) throw Error("Invalid Pipedrive search");
  if (items.length) {
    const people = items.map(({ item }) => {
      if (
        !Number.isSafeInteger(item?.id) ||
        item.id < 1 ||
        typeof item.name !== "string" ||
        !item.name
      )
        throw Error("Invalid matching person");
      return { id: item.id, name: item.name };
    });
    return { people };
  }
  const { person } = await context.actions.call("pipedrive.create_person", {
    name: owner,
    emails: [{ value: email }],
  });
  if (
    !Number.isSafeInteger(person?.id) ||
    person.id < 1 ||
    typeof person.name !== "string" ||
    !person.name
  )
    throw Error("Person creation returned no usable person");
  return { people: [{ id: person.id, name: person.name }] };
}

