export default function next({ people, repo, url, previous }) {
  const index = previous?.index ?? 0;
  if (index === people.length) return { state: { index }, more: false, body: {} };
  const person = people[index];
  if (!Number.isSafeInteger(person?.id) || typeof person?.name !== "string")
    throw Error("Invalid person");
  return {
    state: { index: index + 1 },
    more: true,
    body: { title: `Repo '${repo}' forked by ${person.name}`, person_id: person.id },
  };
}

