export default function result({ statusCode, body, url }) {
  if (
    statusCode < 200 ||
    statusCode >= 300 ||
    body?.success !== true ||
    typeof body?.data?.id !== "string" ||
    !body.data.id
  )
    throw Error("Lead creation did not return a valid ID");
  const safe = url
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
  return { body: { lead_id: body.data.id, content: "Github user url: " + safe } };
}

